Delaire_BO.ModeleAnalyse.PointCtByScript.RecalculateScript:
PointF returnedPoint; 

float angle = 90;


if (patient.Sexe==Delaire_BO.Patient.SexeEnum.M)
{
	if (patient.AgeAnnee<13) angle = 85;
	if (patient.AgeAnnee==13) angle = 86;
	if (patient.AgeAnnee==14) angle = 87;
	if (patient.AgeAnnee==15) angle = 88;
	if (patient.AgeAnnee==16) angle = 89;
	if (patient.AgeAnnee>16) angle = 90;

}
if (patient.Sexe==Delaire_BO.Patient.SexeEnum.F) angle = 85;


float correction = 0;

	//Angle Anterieur Base du crane (C1/C2)   
	float C1C2 = Delaire2010Fonctions.ValeurDe("C1/C2 (anterior angle of the base of the skull)");
	Delaire2010Fonctions.Console("C1C2 = "+C1C2.ToString()+"°");

	if ((C1C2>22) && (C1C2<180))  correction = correction+(0.5f*((int)C1C2-22));                  
	if ((C1C2<20) && (C1C2>0))  correction = correction-(0.5f*(20-(int)C1C2));                


	//Angle (C1/C4)   
	float C1C4 = Delaire2010Fonctions.ValeurDe("C1/C4 (posterior angle of the base of the skull)",117f);
	Delaire2010Fonctions.Console("C1C4 = "+C1C4.ToString()+"°");
	if ((C1C4>120) && (C1C4<180))  correction = correction-(0.25f*((int)C1C4-120));                  
	if ((C1C4<115) && (C1C4>0))  correction = correction+(0.25f*(115-(int)C1C4));       

	

returnedPoint = Delaire2010Fonctions.AngleAvec("FM", "Mp",angle+correction); 
return returnedPoint;

PointF returnedPoint;


returnedPoint = Delaire2010Fonctions.IdentiqueA("Pti");

if (option!=null)
{
      if (option["F4 passing through"] == "Np Calculé")
		returnedPoint = Delaire2010Fonctions.IdentiqueA("Np Calcule");
      if (option["F4 passing through"] == "Pti")
		returnedPoint = Delaire2010Fonctions.IdentiqueA("Pti");
      if (option["F4 passing through"] == "Np Construit")
		returnedPoint = Delaire2010Fonctions.IdentiqueA("NPSurF1M");
      if (option["F4 passing through"] == "ENA")
		returnedPoint = Delaire2010Fonctions.IdentiqueA("ENA");
     if (option["F4 passing through"] == "Od")
		returnedPoint = Delaire2010Fonctions.IdentiqueA("Od");
      if (option["F4 passing through"] == "Np Construit/Od")
		returnedPoint = Delaire2010Fonctions.CentreDe("Od","NPSurF1M");
     if (option["F4 passing through"] == "Od/Go")
		returnedPoint = Delaire2010Fonctions.CentreDe("Od","refGo");
      if (option["F4 passing through"] == "Go")
		returnedPoint = Delaire2010Fonctions.IdentiqueA("refGo");
     if (option["F4 passing through"] == "Point Option")
		returnedPoint = Delaire2010Fonctions.IdentiqueA("Point Option");
	 if (option["F4 passing through"] == "Pti/Od")
		returnedPoint = Delaire2010Fonctions.CentreDe("Od","Pti");
	if (option["F4 passing through"] == "Go/ENA")
		returnedPoint = Delaire2010Fonctions.CentreDe("refGo","ENA");
	if (option["F4 passing through"] == "ENA/Od")
		returnedPoint = Delaire2010Fonctions.CentreDe("Od","ENA");
if (option["F4 passing through"] == "Pt Option")
		returnedPoint = Delaire2010Fonctions.IdentiqueA("Pt opt");
if (option["F4 passing through"] == "Pti/ENA")
		returnedPoint = Delaire2010Fonctions.CentreDe("Pti","ENA");

     
}

Delaire2010Fonctions.Console("F4 passe par "+option["F4 passing through"]);

return returnedPoint;

Limit2.RecalculateScript:
PointF ProjNSurF5 = Delaire2010Fonctions.Projection("F5","N");

float DistNENAt = Delaire2010Fonctions.DistanceEnPxl(ProjNSurF5,"ENA_Theo");

float ratio = 2.22f;

/*
if  (patient.PopulationReference == Delaire_BO.Patient.PopRefEnum.CentreAfricaine)
    ratio = 2.26f;
else
   if  (patient.PopulationReference == Delaire_BO.Patient.PopRefEnum.NordAfricaine)
       ratio = 2.43f;
   else
       ratio = 2.22f;
*/

if (option["proportions"] == "45:55%") ratio = 2.22f;
if (option["proportions"] == "43:57%") ratio = 2.26f;
if (option["proportions"] == "41:59%") ratio = 2.43f;


// 45/55 -> 2.22f
//43/57 --> 2.26f
//41/59-->2.43f


DistNENAt = -DistNENAt * ratio;


PointF MeTheoSurF5 = Delaire2010Fonctions.ParcourirEnPxl("F5",ProjNSurF5,DistNENAt,new PointF(0,0));

return Delaire2010Fonctions.Projection("F1",MeTheoSurF5);

Delaire_BO.ModeleAnalyse.PointCtByScript.RecalculateScript:
/*PointF returnedPoint;
returnedPoint = Delaire2010Fonctions.IntersectionDePlan("F4","F5_tmp");
return returnedPoint;
*/

PointF ProjNPrimSurC1 = Delaire2010Fonctions.Projection("C1","N");
float DistFMNPrim = Delaire2010Fonctions.DistanceEnPxl("FM",ProjNPrimSurC1);

PointF ProjFMSurF4 = Delaire2010Fonctions.Projection("F4","FM");
float DistFMF4 = Delaire2010Fonctions.DistanceEnPxl(ProjFMSurF4,"FM");

float x = DistFMF4*0.087f;

return Delaire2010Fonctions.ParcourirEnPxl("F4","NP_Theo",DistFMNPrim+x,new PointF(5000,5000));

point1.RecalculateScript:
PointF returnedPoint;
returnedPoint = Delaire2010Fonctions.Projection("F5", "Me_Theo");
return returnedPoint;

Droite C1ParN = Delaire2010Fonctions.CreateDroiteParalleleA("C1","N");

float decalage = 1;

if (patient.Sexe==Delaire_BO.Patient.SexeEnum.M)
{
  if ((patient.AgeAnnee>6) && (patient.AgeAnnee<12)) decalage = 2;
  if (patient.AgeAnnee>12) decalage = 3;
}

if (patient.Sexe==Delaire_BO.Patient.SexeEnum.F)
    if (patient.AgeAnnee>6) decalage = 2;



PointF sameAsPt = new PointF(5000,5000);	
return Delaire2010Fonctions.Parcourir(C1ParN,"N",decalage,sameAsPt);

Delaire_BO.ModeleAnalyse.PointCtByScript.RecalculateScript:
 Droite d = Delaire2010Fonctions.CreateDroitePerpendiculaireA("C1","ENA_Theo");

PointF F5F8 = Delaire2010Fonctions.IntersectionDePlan("F8",d);
Droite d2 = Delaire2010Fonctions.CreateDroiteParalleleA("F4",F5F8);
return Delaire2010Fonctions.Parcourir(d2,F5F8,1.5f,new PointF(0,0));

Droite d = Delaire2010Fonctions.CreateDroitePerpendiculaireA("C1","ENA_Theo");


PointF F5F8 = Delaire2010Fonctions.IntersectionDePlan("F8",d);
return Delaire2010Fonctions.Parcourir("F8",F5F8,3,new PointF(0,0));

Delaire_BO.ModeleAnalyse.DiagnosticByScr.RecalculateScript:
float ChampCranioFacial  = Delaire2010Fonctions.DistanceEnPxl("M","Cpth");
float ChampMaxilaire = Delaire2010Fonctions.DistanceEnPxl("Pts","Cpth");
return ChampMaxilaire/ChampCranioFacial;

float ChampCranioFacial  = Delaire2010Fonctions.DistanceEnPxl("M","Cpth");
float ChampMandibulaire = Delaire2010Fonctions.DistanceEnPxl("Pts","M");
return ChampMandibulaire/ChampCranioFacial;

Delaire_BO.ModeleAnalyse.PointCtByScript.RecalculateScript:
PointF returnedPoint; 

float angle = 90;


if (patient.Sexe==Delaire_BO.Patient.SexeEnum.M)
{
	if (patient.AgeAnnee<13) angle = 85;
	if (patient.AgeAnnee==13) angle = 86;
	if (patient.AgeAnnee==14) angle = 87;
	if (patient.AgeAnnee==15) angle = 88;
	if (patient.AgeAnnee==16) angle = 89;
	if (patient.AgeAnnee>16) angle = 90;

}
if (patient.Sexe==Delaire_BO.Patient.SexeEnum.F) angle = 85;




returnedPoint = Delaire2010Fonctions.AngleAvec("FM", "Mp",angle); 
